"""Usage tracker: records each weekly reconcile run per restaurant so pilot usage is measured directly."""
import csv, sys, datetime, os
LOG = "usage_log.csv"
def record(restaurant, week):
    new = not os.path.exists(LOG)
    with open(LOG, "a", newline="") as f:
        w = csv.writer(f)
        if new: w.writerow(["date", "restaurant", "week", "runs_completed"])
        w.writerow([datetime.date.today().isoformat(), restaurant, week, 1])
def summary():
    if not os.path.exists(LOG): print("no usage yet"); return
    counts = {}
    for row in csv.DictReader(open(LOG)):
        counts[row["restaurant"]] = counts.get(row["restaurant"], 0) + int(row["runs_completed"])
    for r, c in sorted(counts.items()): print(f"{r}: {c} weekly runs")
if __name__ == "__main__":
    if len(sys.argv) == 4 and sys.argv[1] == "record": record(sys.argv[2], sys.argv[3])
    else: summary()
EOF
cat >> README.md <<'EOF'

## Usage tracking
`python3 usage_log.py record <restaurant> <week>` logs a completed weekly run; `python3 usage_log.py` prints usage per restaurant.
EOF
